const t = $("Sub").item.json;
const body = {
  query: "query GetAttachments($issueId: String!) { issue(id: $issueId) { attachments { nodes { id url title metadata } } } }",
  variables: { issueId: t.issueId }
};
return { json: { graphqlBody: JSON.stringify(body), operation: t.operation, issueId: t.issueId, runId: t.runId, state: t.state } };

const t = $("Prepare Query").item.json;
const operation = t.operation || "get";
const issueId = t.issueId;
const requestRunId = t.runId || "";
let partialState = t.state;
if (typeof partialState === "string") { try { partialState = JSON.parse(partialState || "{}"); } catch(e) { partialState = {}; } }
if (!partialState || typeof partialState !== "object") { partialState = {}; }
const DEFAULT_STATE = {"schemaVersion":1,"status":"IDLE","runId":null,"startedAt":null,"finishedAt":null,"attempts":0,"clarificationRounds":0,"phase":null,"workflowIds":[],"lastProcessedCommentId":null,"rollingSummary":"","pendingFeedback":[],"halted":false};
const queryResult = $json;
const attachments = queryResult.data?.issue?.attachments?.nodes || [];
const darwinAtt = attachments.find(a => a.url === "darwin://build-state");
let currentState = { ...DEFAULT_STATE };
if (darwinAtt?.metadata) {
  const m = darwinAtt.metadata;
  if (typeof m === "object") { Object.assign(currentState, m); }
  else if (typeof m === "string") { try { Object.assign(currentState, JSON.parse(m)); } catch(e) {} }
}
if (operation === "get") {
  return { json: { route: "return", state: currentState, issueId } };
}
// Optimistic concurrency: only reject if a build is actively RUNNING with a different runId
if (currentState.status === "RUNNING" && currentState.runId && requestRunId && currentState.runId !== requestRunId) {
  return { json: { route: "superseded", storedRunId: currentState.runId, requestRunId, issueId } };
}
let mergedState;
let drainedFeedback = null;
if (operation === "queue") {
  const existingPending = Array.isArray(currentState.pendingFeedback) ? currentState.pendingFeedback : [];
  const newPending = Array.isArray(partialState.pendingFeedback) ? partialState.pendingFeedback : [];
  mergedState = { ...currentState, pendingFeedback: existingPending.concat(newPending), schemaVersion: 1 };
} else if (operation === "drain") {
  drainedFeedback = Array.isArray(currentState.pendingFeedback) ? currentState.pendingFeedback : [];
  mergedState = { ...currentState, pendingFeedback: [], schemaVersion: 1 };
} else {
  mergedState = { ...currentState, ...partialState, schemaVersion: 1 };
}
if (darwinAtt) {
  const body = { query: "mutation UpdateAttachment($id: String!, $title: String!, $metadata: JSONObject!) { attachmentUpdate(id: $id, input: { title: $title, metadata: $metadata }) { success attachment { id url title metadata } } }", variables: { id: darwinAtt.id, title: "Darwin Build State", metadata: mergedState } };
  return { json: { route: "update", attachmentId: darwinAtt.id, graphqlBody: JSON.stringify(body), mergedState, drainedFeedback, issueId } };
} else {
  const body = { query: "mutation CreateAttachment($input: AttachmentCreateInput!) { attachmentCreate(input: $input) { success attachment { id url title metadata } } }", variables: { input: { issueId, url: "darwin://build-state", title: "Darwin Build State", metadata: mergedState } } };
  return { json: { route: "create", graphqlBody: JSON.stringify(body), mergedState, drainedFeedback, issueId } };
}

const p = $("Process").item.json;
const r = $json;
const errors = r.errors || (r.error ? [r.error] : null);
const success = r.data?.attachmentUpdate?.success ?? r.data?.attachmentCreate?.success ?? false;
const attachment = r.data?.attachmentUpdate?.attachment ?? r.data?.attachmentCreate?.attachment ?? null;
return {
  json: {
    ok: success && !errors,
    status: success ? "ok" : "error",
    errors: errors ? errors.map(e => e.message || JSON.stringify(e)).join("; ") : null,
    state: p.mergedState,
    pendingFeedback: p.drainedFeedback || [],
    attachmentId: attachment?.id || p.attachmentId || null,
    issueId: p.issueId
  }
};

const p = $("Process").item.json;
if (p.route === "superseded") {
  return { json: { ok: false, status: "superseded", storedRunId: p.storedRunId, requestRunId: p.requestRunId, issueId: p.issueId, message: "Build state was superseded by another run. Discard this write." } };
}
return { json: { ok: true, status: "ok", state: p.state, issueId: p.issueId } };
